rule.definition:
a!localVariables(
  local!ccForAskSubmittedToLeadershipGroup: if(
    #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[2] = ri!statusId,
    {
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177083",
      #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066240",
      #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066222",
      #"_a-0000e825-ace1-8000-9c24-011c48011c48_6814637",
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177108",
      /*replacement grp for DPP Chief of Staff*/
      #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11723973"
    },
    null
  ),
  local!ccForLeadershipApprovalorReturnGroup: if(
    and(
      contains(
        {
          #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3373079",
          #"_a-0000e825-ace1-8000-9c24-011c48011c48_6791426"
        },
        ri!statusId
      ),
      ri!previousStatusId = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[2]
    ),
    {
      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3177083",
      #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066240",
      #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14066222",
      #"_a-0000e825-ace1-8000-9c24-011c48011c48_6814637"
    },
    null
  ),
  local!recipientccUsers: if(
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(
      local!ccForAskSubmittedToLeadershipGroup
    ),
    #"SYSTEM_SYSRULES_forEach"(
      items: local!ccForAskSubmittedToLeadershipGroup,
      expression: a!groupMembers(group: fv!item)
    ),
    if(
      #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(
        local!ccForLeadershipApprovalorReturnGroup
      ),
      #"SYSTEM_SYSRULES_forEach"(
        items: local!ccForLeadershipApprovalorReturnGroup,
        expression: a!groupMembers(fv!item)
      ),
      null
    )
  ),
  local!recipients: if(
    #"_a-0000e375-1fcb-8000-daab-640000640000_930460"(local!recipientccUsers),
    #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(
      a!flatten(
        #"SYSTEM_SYSRULES_forEach"(
          items: local!recipientccUsers,
          expression: property(fv!item, "data", null)
        )
      )
    ),
    null
  ),
  if(
    ri!statusId = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3295646",
    #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(
      toemailrecipient(toemailaddress(ri!askSubmittedBy))
    ),
    if(
      ri!statusId = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[1],
      #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(
        toemailrecipient(
          toemailaddress(#"_a-0000e72d-09a6-8000-9c0e-011c48011c48_4718496")
        )
      ),
      if(
        and(
          ri!statusId = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3373079",
          ri!previousStatusId = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[2]
        ),
        #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(
          toemailrecipient(toemailaddress(local!recipients))
        ),
        if(
          and(
            ri!statusId = #"_a-0000e825-ace1-8000-9c24-011c48011c48_6791426",
            ri!previousStatusId = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[2]
          ),
          #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(
            toemailrecipient(
              toemailaddress({ local!recipients, ri!askSubmittedBy })
            )
          ),
          if(
            ri!statusId = #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3256063"[2],
            #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11617061"(
              toemailrecipient(
                toemailaddress({ local!recipients, ri!askSubmittedBy })
              )
            ),
            null
          )
        )
      )
    )
  )
)
